textOptions.schema:
{
  "type": "object",
  "properties": {
    "fit_score": {
      "type": "object",
      "properties": {
        "rating": {
          "type": "integer",
          "description": "Overall fit score on a scale of 1 to 5.",
          "minimum": 1,
          "maximum": 5
        },
        "out_of": {
          "type": "integer",
          "description": "Maximum possible fit score.",
          "const": 5
        },
        "summary": {
          "type": "string",
          "description": "A concise summary explaining the overall fit."
        }
      },
      "required": [
        "rating",
        "out_of",
        "summary"
      ],
      "additionalProperties": false
    },
    "strengths": {
      "type": "array",
      "description": "List of key strengths that match the job requirements.",
      "items": {
        "type": "string"
      }
    },
    "gaps": {
      "type": "array",
      "description": "List of missing or weak requirements relevant to the job.",
      "items": {
        "type": "string"
      }
    },
    "recommendation": {
      "type": "object",
      "properties": {
        "decision": {
          "type": "string",
          "description": "Overall hiring recommendation.",
          "enum": [
            "Highly Recommended",
            "Recommended",
            "Consider",
            "Not Recommended"
          ]
        },
        "reason": {
          "type": "string",
          "description": "Brief justification for the recommendation."
        }
      },
      "required": [
        "decision",
        "reason"
      ],
      "additionalProperties": false
    }
  },
  "required": [
    "fit_score",
    "strengths",
    "gaps",
    "recommendation"
  ],
  "additionalProperties": false
}

{
  "type": "object",
  "properties": {
    "subject": {
      "type": "string",
      "description": "Professional subject line for the cover letter or application email."
    },
    "cover_letter": {
      "type": "string",
      "description": "Complete professional cover letter with paragraph breaks."
    }
  },
  "required": [
    "subject",
    "cover_letter"
  ],
  "additionalProperties": false
}
